Code:
class User {
    User(String name) {}
}
User u = new User();

class User {
    String name;
    User(String name) {
        this.name = name;
    }
}
System.out.println(new User("Ana").name);

class User {
    String name;
    User(String name) {
        name = name;
    }
}

Student a = new Student("Alice");
Student b = a;
b.name = "Bob";
System.out.println(a.name);

class Team {
    private List<String> members = new ArrayList<>();
    List<String> getMembers() { return members; }
}

class Parent {
    Parent(String name) {}
}
class Child extends Parent {
    Child() {}
}

class Animal { void speak() { System.out.print("A"); } }
class Dog extends Animal { void speak() { System.out.print("D"); } }
Animal a = new Dog();
a.speak();

class Parent { int x = 1; }
class Child extends Parent { int x = 2; }
Parent p = new Child();
System.out.println(p.x);

class Parent { static void show() { System.out.print("P"); } }
class Child extends Parent { static void show() { System.out.print("C"); } }
Parent p = new Child();
p.show();

class Child extends Parent {
    void print() {
        super.print();
    }
}

class Food {}
class Meat extends Food {}
class Animal { Food food() { return new Food(); } }
class Tiger extends Animal { Meat food() { return new Meat(); } }

interface Loggable {
    default void log() { helper(); }
    private void helper() {}
}

